fun localizedProductName(id: String, name: String): String =
    catalogDisplay[id]?.takeIf { it.name == name }?.let { tr(it.nameResource) } ?: name

fun Product.localizedName(): String = localizedProductName(id, name)
fun Entry.localizedName(): String = localizedProductName(productId, name)

fun Product.localizedCategory(): String =
    if (category in appOwnedCategories) categoryLabel(category)
    else catalogDisplay[id]?.takeIf { it.category == category }?.let { tr(it.categoryResource) } ?: category

fun Product.localizedNote(): String =
    catalogDisplay[id]?.takeIf { it.note == note }?.let { tr(it.noteResource, it.sourceId) } ?: note

private val categoryResources = mapOf(
    "Фрукты и ягоды" to R.string.data_category_fruit,
    "Сухофрукты" to R.string.data_category_dried_fruit,
    "Овощи и зелень" to R.string.data_category_vegetables,
    "Грибы" to R.string.data_category_mushrooms,
    "Крупы и макароны" to R.string.data_category_grains,
    "Бобовые" to R.string.data_category_legumes,
    "Мясо и птица" to R.string.data_category_meat,
    "Рыба и морепродукты" to R.string.data_category_fish,
    "Молочные продукты" to R.string.data_category_dairy,
    "Яйца" to R.string.data_category_eggs,
    "Масла" to R.string.data_category_oils,
    "Орехи и семена" to R.string.data_category_nuts,
    "Хлеб" to R.string.data_category_bread,
    "Другие продукты" to R.string.data_category_other,
    "Готовые блюда" to R.string.data_category_dishes,
    "Мои продукты" to R.string.data_category_custom,
    "Мои блюда" to R.string.data_category_my_dishes,
    "Другое" to R.string.data_category_other_short,
 )

// These labels are written by the app's own product/recipe controls, including older versions.
// All other custom category text is preserved verbatim, even if it resembles a seed category.
private val appOwnedCategories = setOf("Мои продукты", "Готовые блюда", "Мои блюда")

/** For predefined category selectors only; free-form custom category text stays untouched. */
fun categoryLabel(canonical: String): String = categoryResources[canonical]?.let { tr(it) } ?: canonical
fun canonicalCategory(displayed: String): String =
    categoryResources.entries.firstOrNull { tr(it.value) == displayed }?.key ?: displayed

/** Existing backup and sync meal values intentionally remain stable across languages. */
fun mealLabel(canonical: String): String = when (canonical) {
    "Завтрак" -> tr(R.string.data_meal_breakfast)
    "Обед" -> tr(R.string.data_meal_lunch)
    "Ужин" -> tr(R.string.data_meal_dinner)
    "Перекус" -> tr(R.string.data_meal_snack)
    else -> canonical
}
